Code.Terraform:
```hcl
# Enable network policy enforcement in the VPC CNI managed add-on
resource "aws_eks_addon" "<example_resource_name>" {
  cluster_name                = "<example_cluster_name>"
  addon_name                  = "vpc-cni"
  resolve_conflicts_on_update = "PRESERVE"

  configuration_values = jsonencode({
    enableNetworkPolicy = "true"  # critical: makes the CNI enforce NetworkPolicy resources
  })
}
```
